import React, { createContext, useState, useEffect, useContext } from 'react';

const API_BASE_URL = 'http://127.0.0.1:8000';

const WordMappingContext = createContext();

export function useWordMappings() {
  return useContext(WordMappingContext);
}

export function WordMappingProvider({ children }) {
  const [mappings, setMappings] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchMappings = async () => {
      try {
        const response = await fetch(`${API_BASE_URL}/words`);
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setMappings(data || {});
      } catch (e) {
        setError(e);
        console.error("Failed to fetch word mappings:", e);
      } finally {
        setLoading(false);
      }
    };

    fetchMappings();
  }, []);

  const value = {
    mappings,
    loading,
    error
  };

  return (
    <WordMappingContext.Provider value={value}>
      {!loading && children}
    </WordMappingContext.Provider>
  );
}

