import React, { useState, useEffect, useMemo } from 'react';
import { Link } from 'react-router-dom';
import LoadingSpinner from '../components/LoadingSpinner';

const API_BASE_URL = 'http://127.0.0.1:8000';

function SchoolCard({ school }) {
  // Assuming the overview table has these columns. 
  // We can make this more robust if needed.
  const schoolName = school.school_name || 'Unknown School';
  const schoolId = school.school_id;
  const description = school.overview || 'No description available.';

  return (
    <div className="col-md-6 col-lg-4 mb-4">
      <div className="card h-100">
        <div className="card-body d-flex flex-column">
          <h5 className="card-title">{schoolName}</h5>
          <p className="card-text flex-grow-1">{description.substring(0, 100)}...</p>
          <Link to={`/schools/${schoolId}`} className="btn btn-primary mt-auto">View Details</Link>
        </div>
      </div>
    </div>
  );
}

function HomePage() {
  const [schools, setSchools] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    const fetchSchools = async () => {
      setLoading(true);
      setError(null);
      try {
        // Assuming 'flattened_overview' contains the main list of schools.
        const response = await fetch(`${API_BASE_URL}/flattened_overview`);
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setSchools(data || []);
      } catch (e) {
        setError(`Failed to fetch schools: ${e.message}`);
      } finally {
        setLoading(false);
      }
    };
    fetchSchools();
  }, []);

  const filteredSchools = useMemo(() => {
    return schools.filter(school => 
      (school.school_name || '').toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [schools, searchTerm]);

  return (
    <div>
      <div className="p-5 mb-4 bg-light rounded-3">
        <div className="container-fluid py-5">
          <h1 className="display-5 fw-bold">Find Your School</h1>
          <p className="col-md-8 fs-4">Browse the list of schools available in our database.</p>
          <input 
            type="text"
            className="form-control form-control-lg mt-4"
            placeholder="Search by school name..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {loading && <LoadingSpinner />}
      {error && <div className="alert alert-danger">Error: {error}</div>}

      <div className="row">
        {!loading && !error && filteredSchools.length === 0 && (
          <div className="col">
            <p className="text-center">No schools found.</p>
          </div>
        )}
        {filteredSchools.map(school => (
          <SchoolCard key={school.school_id} school={school} />
        ))}
      </div>
    </div>
  );
}

export default HomePage;

import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import LoadingSpinner from '../components/LoadingSpinner';
import { useWordMappings } from '../contexts/WordMappingContext';

const API_BASE_URL = 'http://127.0.0.1:8000';

function SchoolDetailPage() {
  const { schoolId } = useParams();
  const { mappings, loading: mappingsLoading, error: mappingsError } = useWordMappings();
  const [schoolData, setSchoolData] = useState({});
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedTopic, setSelectedTopic] = useState('all');

  useEffect(() => {
    if (!schoolId || mappingsLoading) return;

    const fetchAllSchoolData = async () => {
      setLoading(true);
      setError(null);
      try {
        const tablesResponse = await fetch(`${API_BASE_URL}/tables`);
        if (!tablesResponse.ok) throw new Error('Failed to fetch table list');
        const tablesData = await tablesResponse.json();
        const tableNames = tablesData.flattened_tables || [];

        const dataPromises = tableNames.map(tableName =>
          fetch(`${API_BASE_URL}/${tableName}/${schoolId}`)
            .then(res => {
              if (res.ok) return res.json();
              if (res.status === 404) return null;
              throw new Error(`Failed to fetch data from ${tableName}`);
            })
        );

        const results = await Promise.all(dataPromises);

        const aggregatedData = {};
        results.forEach((data, index) => {
          if (data) {
            const topicName = tableNames[index].replace('flattened_', '');
            aggregatedData[topicName] = data;
          }
        });

        setSchoolData(aggregatedData);

      } catch (e) {
        setError(e.message);
        console.error("Failed to fetch school details:", e);
      } finally {
        setLoading(false);
      }
    };

    fetchAllSchoolData();
  }, [schoolId, mappingsLoading]);

  const getDisplayName = (key) => {
    return mappings[key]?.ja || key.replace(/_/g, ' ');
  };

  const isLoading = loading || mappingsLoading;
  const schoolName = schoolData.overview?.school_name || 'School Details';

  const filteredData = selectedTopic === 'all' 
    ? schoolData 
    : { [selectedTopic]: schoolData[selectedTopic] };

  return (
    <div>
      <Link to="/" className="btn btn-secondary mb-4"> &larr; Back to School List</Link>

      {isLoading && <LoadingSpinner />}
      {error && <div className="alert alert-danger">Error: {error}</div>}
      {mappingsError && <div className="alert alert-warning">Could not load translations: {mappingsError.message}</div>}

      {!isLoading && !error && (
        <div className="card">
          <div className="card-header d-flex justify-content-between align-items-center">
            <h1 className="card-title mb-0">{schoolName}</h1>
            <div className="col-md-4">
              <select className="form-select" value={selectedTopic} onChange={(e) => setSelectedTopic(e.target.value)}>
                <option value="all">すべて表示</option>
                {Object.keys(schoolData).map(topic => (
                  <option key={topic} value={topic}>{getDisplayName(topic)}</option>
                ))}
              </select>
            </div>
          </div>
          <div className="card-body">
            {Object.entries(filteredData).map(([topic, details]) => {
              if (!details) return null; // In case a selected topic has no data
              return (
                <div key={topic} className="mb-4">
                  <h4 className="text-capitalize fw-bold">{getDisplayName(topic)}</h4>
                  <ul className="list-group list-group-flush">
                    {Object.entries(details).map(([key, value]) => {
                      if (['school_id', 'source_topic_table', 'source_topic_key', 'source_data_source'].includes(key)) {
                        return null;
                      }
                      return (
                        <li key={key} className="list-group-item d-flex flex-wrap">
                          <strong className="text-capitalize col-12 col-md-3">{getDisplayName(key)}:</strong>
                          <span className="ms-2 col-12 col-md-8">{String(value)}</span>
                        </li>
                      );
                    })}
                  </ul>
                </div>
              )
            })}
          </div>
        </div>
      )}
    </div>
  );
}

export default SchoolDetailPage;

